# Reverse the encode process to recover the flag

def up(x):
    x = [f"{ord(x[i]) << 1:08b}" for i in range(len(x))]
    return ''.join(x)

def down(x):
    x = ''.join(['1' if x[i] == '0' else '0' for i in range(len(x))])
    return x

def right(x,d):
    x = x[d:] + x[0:d]
    return x

def left(x,d):
    x = right(x,len(x)-d)
    return x[::-1]

# Inverse functions

def inv_left(x, d):
    # left(x, d) = right(x, len(x)-d)[::-1]
    # To invert: reverse, then left by (len(x)-d)
    x = x[::-1]
    return right(x, len(x)-d)

def inv_down(x):
    # down(x): flip 0<->1, so same as itself
    return down(x)

def inv_right(x, d):
    # right(x, d): x[d:] + x[:d]
    # Inverse: right(x, len(x)-d)
    return right(x, len(x)-d)

def inv_up(x):
    # up(x): [ord(c)<<1:08b for c in plain], join
    # Inverse: split into 8 bits, shift right by 1, chr
    chars = []
    for i in range(0, len(x), 8):
        b = x[i:i+8]
        c = chr(int(b, 2) >> 1)
        chars.append(c)
    return ''.join(chars)

encoded = "1010000011111000101010101000001010100100110110001111111010001000100000101000111011000100101111011001100011011000101011001100100010011001110110001001000010001100101111001110010011001100"

d = 24

# Inverse order: left, down, right, up
x = encoded
x = inv_left(x, d)
x = inv_down(x)
x = inv_right(x, d)
flag = inv_up(x)
print(flag)
